cypress_script:
describe('Select Menu Widgets', () => {
  it('should allow a user to select a car from the dropdown', () => {
    cy.visit('https://demoqa.com/select-menu');
    cy.get('#cars').select('Volvo');
    cy.get('#cars').should('have.value', 'volvo');
  });
  it('should not change URL on selecting an option', () => {
    cy.visit('https://demoqa.com/select-menu');
    cy.get('#cars').select('Saab');
    cy.url().should('eq', 'https://demoqa.com/select-menu');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Select Menu Widgets', () => {
  test('should allow a user to select a car from the dropdown', async ({ page }) => {
    await page.goto('https://demoqa.com/select-menu');
    await page.selectOption('#cars', 'volvo');
    const value = await page.locator('#cars').inputValue();
    expect(value).toBe('volvo');
  });
  test('should not change URL on selecting an option', async ({ page }) => {
    await page.goto('https://demoqa.com/select-menu');
    await page.selectOption('#cars', 'saab');
    expect(page.url()).toBe('https://demoqa.com/select-menu');
  });
});
